using System;
using System.Collections;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using UnityEngine;

// Explicit opt-in player acceptance. Uses the isolated content-test campaign only.
public sealed class ChoiceEffectsPlayerCheck:MonoBehaviour {
 int checks;float began;bool dialogueVisual,dialogueReady;PassengerDialogueUI.Option[] dialogueOptions;
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)] static void Install(){if(Array.IndexOf(Environment.GetCommandLineArgs(),"-choiceEffectsPlayerCheck")>=0||Array.IndexOf(Environment.GetCommandLineArgs(),"-choiceEffectsDialogueCheck")>=0){var go=new GameObject("Choice effects player acceptance");DontDestroyOnLoad(go);go.AddComponent<ChoiceEffectsPlayerCheck>();}}
 void Check(bool ok,string label){checks++;Debug.Log("CHOICE_EFFECTS_PLAYER "+(ok?"PASS ":"FAIL ")+label);if(!ok)throw new Exception(label);}
 void Near(double a,double b,string label){Check(Math.Abs(a-b)<.00001,label+" actual="+a+" expected="+b);}
 DriveSession Human(){foreach(var s in FindObjectsOfType<DriveSession>())if(!s.IsSimulationBot)return s;return null;}
 IEnumerator Ready(){while(!Human()||!Human().StartupReady||!Human().business||Human().business.IsRestoring)yield return null;yield return null;}
 void Update(){if(dialogueVisual&&dialogueReady&&Time.realtimeSinceStartup-began>150){Debug.Log("CHOICE_DIALOGUE_VISUAL_CLOSED");Application.Quit(0);return;}if(Time.realtimeSinceStartup-began>180){Debug.LogError("CHOICE_EFFECTS_PLAYER timeout");Application.Quit(2);}}
 IEnumerator Start(){began=Time.realtimeSinceStartup;dialogueVisual=Array.IndexOf(Environment.GetCommandLineArgs(),"-choiceEffectsDialogueCheck")>=0;var run=dialogueVisual?DialogueVisual():Run();while(true){object next;try{if(!run.MoveNext())yield break;next=run.Current;}catch(Exception e){Debug.LogError("CHOICE_EFFECTS_PLAYER_EXCEPTION "+e);Application.Quit(2);yield break;}yield return next;}}
 IEnumerator DialogueVisual(){
  Check(ContentTuningRuntime.TestMode,"visual fixture requires isolated content test mode");yield return null;FindObjectOfType<UnifiedModeBootstrap>().StartSingle();yield return Ready();var session=Human();FreezeClock(session);session.paused=true;session.enabled=false;Time.timeScale=0;
  var choices=PassengerRequestChoices.For(RequestKind.Empathy);dialogueOptions=new PassengerDialogueUI.Option[choices.Length];
  for(int i=0;i<choices.Length;i++){string repeated="";for(int line=0;line<7;line++)repeated+=(line>0?"\n":"")+"설명 "+(line+1)+" · "+choices[i].effect;dialogueOptions[i]=new PassengerDialogueUI.Option(i==0?"Y":i==1?"I":"U",choices[i].label,repeated);}
  dialogueReady=true;Debug.Log("CHOICE_DIALOGUE_READY manual wheel/click fixture; profile unchanged; closes after150 realtime seconds");
 }
 void OnGUI(){if(!dialogueVisual||!dialogueReady)return;int oldDepth=GUI.depth;GUI.depth=-1000;int chosen=PassengerDialogueUI.Draw("선택지 효과 스크롤 검사","오늘 속상한 일이 있었어요. 긴 효과 설명을 아래로 스크롤해 마지막 답변까지 확인해 주세요.",dialogueOptions,"수동 화면 검사 전용 · 실제 요청 답변/효과 설명을 반복 표시 · Y/I/U 보상/운행 처리 없음");if(chosen>=0)Debug.Log("CHOICE_DIALOGUE_CLICK index="+chosen);GUI.depth=oldDepth;}
 void FreezeClock(DriveSession s){s.business.preparing=false;s.paused=false;Time.timeScale=1;s.jobs.enabled=false;s.business.enabled=false;s.requests.enabled=false;s.law.enabled=false;s.manners.enabled=false;s.taxi.enabled=false;s.taxi.body.velocity=s.taxi.body.angularVelocity=Vector3.zero;s.taxi.body.isKinematic=true;}
 void Place(DriveSession s,MapStop stop){var t=s.taxi;t.body.position=stop.Kerb+Vector3.up*.65f;t.body.rotation=Quaternion.LookRotation(stop.Direction);t.transform.SetPositionAndRotation(t.body.position,t.body.rotation);Physics.SyncTransforms();s.law.ResetObservation();s.manners.Suppress(1);}
 void Clock(DriveSession s,double seconds){typeof(EconomyLedger).GetProperty("Elapsed").SetValue(s.business.ledger,seconds,null);}
 void Set(Dictionary<string,object> p,string key,double value){foreach(object o in ContentJson.Array(p["values"])){var row=ContentJson.Object(o);if((string)row["id"]==key){row["value"]=value.ToString(CultureInfo.InvariantCulture);return;}}throw new Exception("Missing fixture key "+key);}
 void Profile(){var p=ContentJson.Object(ContentJson.Parse(ContentTuningRuntime.Snapshot()));foreach(object o in ContentJson.Array(p["values"])){var row=ContentJson.Object(o);if(((string)row["id"]).StartsWith("choice.",StringComparison.Ordinal))row["value"]="0";}Set(p,"choice.effects.version",1);Set(p,"choice.request.Eta.EtaFaster.immediate.satisfaction",9);Set(p,"choice.request.Empathy.Accept.immediate.satisfaction",3);Set(p,"choice.request.Empathy.Accept.immediate.fatigue",2);Set(p,"choice.request.Empathy.Accept.during.satisfactionPerMinute",6);Set(p,"choice.request.Empathy.Accept.during.fatiguePerMinute",1);Set(p,"choice.request.Empathy.Accept.during.fatigueGrowthPercent",100);Set(p,"choice.request.Empathy.Accept.end.success.satisfaction",7);Set(p,"choice.request.Empathy.Accept.end.success.fatigue",3);Set(p,"choice.request.Empathy.Accept.end.success.satisfactionPercent",10);p["contentHash"]=ContentTuning.ComputeHash(p);ContentTuningRuntime.Restore(ContentJson.Stringify(p));}
 void Board(DriveSession s){Array.Clear(s.jobs.cooldown,0,s.jobs.cooldown.Length);s.jobs.ForcedPassengerType=PassengerType.General;bool accepted=false;for(int i=0;i<s.jobs.offers.Length;i++)if(s.jobs.offers[i]!=null&&s.jobs.Accept(i)){accepted=true;break;}Check(accepted,"real job accepted");Place(s,s.jobs.stops[s.jobs.current.pickup]);Check(s.jobs.Interact()&&s.jobs.trip.State==TripState.OnTrip,"real Interact boards passenger");Check(s.jobs.Behavior.Type==PassengerType.General&&s.jobs.ChoiceEffectsActive,"general passenger uses choice ledger");typeof(PassengerJobs).GetProperty("StartSatisfaction").SetValue(s.jobs,70,null);}
 IEnumerator Run(){
  Check(ContentTuningRuntime.TestMode,"explicit isolated content test mode");yield return null;FindObjectOfType<UnifiedModeBootstrap>().StartSingle();yield return Ready();var s=Human();FreezeClock(s);Profile();Check(s.business.SavePath.StartsWith(ContentTuningRuntime.TestDirectory+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase),"isolated campaign path");Board(s);
  s.requests.BeginKind(RequestKind.Eta);Check(s.requests.Choose(PassengerReply.EtaNormal),"real ETA normal reply");Near(s.jobs.ChoiceEffects.SatisfactionDelta,0,"ETA normal independent of changed faster reply");string etaNormalId=s.law.tripId+":request:Eta";Place(s,s.jobs.stops[s.jobs.current.drop]);Check(s.jobs.Interact(),"ETA normal actual delivery");Near(s.jobs.ChoiceEffects.RequestEndFor(etaNormalId),0,"ETA normal zero end");
  s.jobs.PrepareForNextCall();Board(s);s.requests.BeginKind(RequestKind.Eta);Check(s.requests.Choose(PassengerReply.EtaFaster),"real ETA faster on separate ride");Near(s.jobs.ChoiceEffects.SatisfactionDelta,9,"ETA faster independently configured immediate");string etaFasterId=s.law.tripId+":request:Eta";Place(s,s.jobs.stops[s.jobs.current.drop]);Check(s.jobs.Interact(),"ETA faster actual delivery");Near(s.jobs.ChoiceEffects.RequestEndFor(etaFasterId),0,"ETA faster independent zero end");
  s.jobs.PrepareForNextCall();Board(s);double f=s.business.ledger.Driver.fatigue;int initial=s.jobs.ScoreView.value;
  s.requests.BeginKind(RequestKind.Empathy);Check(s.requests.Choose(PassengerReply.Accept),"real Empathy accept reply");string eventId=s.law.tripId+":request:Empathy";Near(s.jobs.ChoiceEffects.SatisfactionDelta,3,"actual immediate satisfaction");Near(s.jobs.ScoreView.value,initial+3,"score view applies immediate");Near(s.business.ledger.Driver.fatigue,f+2,"actual immediate fatigue");Near(s.business.ledger.Driver.choiceFatigueGrowthPercent,100,"actual natural fatigue modifier");Check(!s.requests.Choose(PassengerReply.Accept),"actual reply cannot repeat");Near(s.business.ledger.Driver.fatigue,f+2,"repeated reply no fatigue");
  Clock(s,s.business.ledger.Elapsed+60);s.jobs.TickChoiceEffects();Near(s.jobs.ChoiceEffects.SatisfactionDelta,9,"business clock one minute satisfaction");Near(s.business.ledger.Driver.fatigue,f+3,"business clock one minute fatigue");s.jobs.TickChoiceEffects();Near(s.jobs.ChoiceEffects.SatisfactionDelta,9,"no duplicate business clock tick");
  Check(s.business.SaveCheckpoint(),"real active checkpoint saved");string path=s.business.SavePath,profile=ContentTuningRuntime.Snapshot();var saved=BusinessProgress.ParseCheckpoint(File.ReadAllText(path));Check(saved.contentProfileJson==profile,"checkpoint stores custom schema2 profile");
  Check(FindObjectOfType<UnifiedModeBootstrap>().ReturnToMenu(),"menu return saves transport");while(Human())yield return null;yield return null;FindObjectOfType<UnifiedModeBootstrap>().StartSingle();yield return Ready();s=Human();FreezeClock(s);Check(s.jobs.trip.State==TripState.OnTrip&&s.business.SavePath==path,"real campaign resumes active transport");Check(ContentTuningRuntime.Snapshot()==profile,"resume restores frozen profile");Check(Math.Abs(s.jobs.ChoiceEffects.SatisfactionDelta-9)<=1,"resume no immediate satisfaction replay");Check(Math.Abs(s.business.ledger.Driver.fatigue-(f+3))<.25,"resume no immediate fatigue replay");Check(s.jobs.ChoiceEffects.HasEvent(eventId),"actual trip identity survives restore");
  Place(s,s.jobs.stops[s.jobs.current.drop]);double before=s.business.ledger.Driver.fatigue;int preEndS=s.jobs.ScoreView.value;int expectedEnd=(int)Math.Round(7+preEndS*.1,MidpointRounding.AwayFromZero);int separate=s.jobs.ChoiceEffects.SatisfactionDelta;Check(s.jobs.Interact(),"real destination Interact completes delivery");Near(s.jobs.ChoiceEffects.RequestEndFor(eventId),expectedEnd,"request end percent uses actual pre-phase satisfaction");Near(s.requests.TotalSatisfactionDelta,ContentTuning.Int("common.requestCap",10),"legacy cap applies only to request end");Near(s.jobs.ChoiceEffects.SatisfactionDelta,separate,"immediate and during remain outside request end cap");Near(s.jobs.RequestReward.satisfactionDelta,separate+ContentTuning.Int("common.requestCap",10),"actual settlement includes uncapped phase contribution plus capped end");Near(s.business.ledger.Driver.fatigue,before+3,"real end applies driver fatigue");int count=s.jobs.ChoiceEffects.entries.Count;Near(s.jobs.CompleteChoiceRequest(RequestKind.Empathy,PassengerReply.Accept,1),0,"finished ride cannot replay end");Near(s.business.ledger.Driver.fatigue,before+3,"finished replay no fatigue");Check(s.jobs.ChoiceEffects.entries.Count==count,"end replay creates no selections");
  s.jobs.PrepareForNextCall();Board(s);s.requests.BeginKind(RequestKind.Empathy);Check(s.requests.Choose(PassengerReply.Accept),"second actual ride choice");s.jobs.CancelChoiceEffects();before=s.business.ledger.Driver.fatigue;int contribution=s.jobs.ChoiceEffects.SatisfactionDelta;Clock(s,s.business.ledger.Elapsed+60);s.jobs.TickChoiceEffects();Near(s.jobs.ChoiceEffects.SatisfactionDelta,contribution,"cancellation freezes satisfaction");Near(s.business.ledger.Driver.fatigue,before,"cancellation freezes extra fatigue");Near(s.business.ledger.Driver.choiceFatigueGrowthPercent,0,"cancellation clears modifier");Near(s.jobs.CompleteChoiceRequest(RequestKind.Empathy,PassengerReply.Accept,1),0,"cancellation suppresses end reward");
  Debug.Log("CHOICE_EFFECTS_PLAYER_OK checks="+checks+" save="+path);Application.Quit(0);
 }
}
